PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS sources (source_id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, source_type TEXT NOT NULL DEFAULT 'threat_intelligence', url TEXT, description TEXT);
CREATE TABLE IF NOT EXISTS iocs (ioc_id INTEGER PRIMARY KEY, value TEXT NOT NULL, canonical_type TEXT NOT NULL, first_seen TEXT, last_seen TEXT, status TEXT, UNIQUE(value, canonical_type));
CREATE TABLE IF NOT EXISTS ioc_sources (ioc_id INTEGER NOT NULL, source_id INTEGER NOT NULL, first_seen TEXT, last_seen TEXT, record_count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (ioc_id, source_id), FOREIGN KEY (ioc_id) REFERENCES iocs(ioc_id) ON DELETE CASCADE, FOREIGN KEY (source_id) REFERENCES sources(source_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS observations (observation_id INTEGER PRIMARY KEY, ioc_id INTEGER NOT NULL, source_id INTEGER NOT NULL, source_record_id TEXT, event_id TEXT, event_uuid TEXT, event_info TEXT, first_seen TEXT, last_seen TEXT, timestamp TEXT, to_ids INTEGER, category TEXT, comment TEXT, threat_type TEXT, malware TEXT, confidence TEXT, reporter TEXT, status TEXT, reference TEXT, tlp TEXT, raw_metadata TEXT, FOREIGN KEY (ioc_id) REFERENCES iocs(ioc_id) ON DELETE CASCADE, FOREIGN KEY (source_id) REFERENCES sources(source_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tags (tag_id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS observation_tags (observation_id INTEGER NOT NULL, tag_id INTEGER NOT NULL, tag_scope TEXT NOT NULL DEFAULT 'record', PRIMARY KEY (observation_id, tag_id, tag_scope), FOREIGN KEY (observation_id) REFERENCES observations(observation_id) ON DELETE CASCADE, FOREIGN KEY (tag_id) REFERENCES tags(tag_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS malware (malware_id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS observation_malware (observation_id INTEGER NOT NULL, malware_id INTEGER NOT NULL, PRIMARY KEY (observation_id, malware_id), FOREIGN KEY (observation_id) REFERENCES observations(observation_id) ON DELETE CASCADE, FOREIGN KEY (malware_id) REFERENCES malware(malware_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS mitre_techniques (technique_id TEXT PRIMARY KEY, name TEXT);
CREATE TABLE IF NOT EXISTS observation_mitre (observation_id INTEGER NOT NULL, technique_id TEXT NOT NULL, PRIMARY KEY (observation_id, technique_id), FOREIGN KEY (observation_id) REFERENCES observations(observation_id) ON DELETE CASCADE, FOREIGN KEY (technique_id) REFERENCES mitre_techniques(technique_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ioc_references (reference_id INTEGER PRIMARY KEY, url TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS observation_references (observation_id INTEGER NOT NULL, reference_id INTEGER NOT NULL, PRIMARY KEY (observation_id, reference_id), FOREIGN KEY (observation_id) REFERENCES observations(observation_id) ON DELETE CASCADE, FOREIGN KEY (reference_id) REFERENCES ioc_references(reference_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vulnerabilities (vulnerability_id INTEGER PRIMARY KEY, cve TEXT NOT NULL UNIQUE, vendor_project TEXT, product TEXT, vulnerability_name TEXT, date_added TEXT, due_date TEXT, short_description TEXT, required_action TEXT, known_ransomware_use TEXT, notes TEXT, cwes TEXT, raw_json TEXT);
CREATE TABLE IF NOT EXISTS enrichments (enrichment_id INTEGER PRIMARY KEY, ioc_id INTEGER NOT NULL, source_id INTEGER, status TEXT, verified INTEGER, message TEXT, checked_at TEXT, raw_json TEXT, FOREIGN KEY (ioc_id) REFERENCES iocs(ioc_id) ON DELETE CASCADE, FOREIGN KEY (source_id) REFERENCES sources(source_id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_iocs_value ON iocs(value);
CREATE INDEX IF NOT EXISTS idx_iocs_type ON iocs(canonical_type);
CREATE INDEX IF NOT EXISTS idx_ioc_sources_source ON ioc_sources(source_id);
CREATE INDEX IF NOT EXISTS idx_observations_ioc ON observations(ioc_id);
CREATE INDEX IF NOT EXISTS idx_observations_source ON observations(source_id);
CREATE INDEX IF NOT EXISTS idx_observations_record ON observations(source_record_id);
CREATE INDEX IF NOT EXISTS idx_tags_name ON tags(name);
CREATE INDEX IF NOT EXISTS idx_malware_name ON malware(name);
